inline QJsonObject candidate(const Catalog &c,int i){const auto &v=c.previews[i];const auto &d=c.draws[v.draw];QJsonArray matrix;for(int k=0;k<16;++k)matrix.append(v.matrix.constData()[k]);QString name=(v.node>=0?c.nodes[v.node].name+" / ":"Unplaced / ")+d.name+QString(" / Material %1 / Draw %2.%3").arg(d.materialName.isEmpty()?QString::number(d.material):d.materialName).arg(d.group).arg(d.part);return {{"name",name},{"profileId","native-faf-arcx"},{"profileName","F&F Xbox ARCX static geometry"},{"nativeDecoder",true},{"triangleCount",d.triangles},{"objectOffset",QString::number(d.descriptor)},{"fafNode",v.node},{"sourceTransform",matrix},{"optionalVariant",v.variant},{"optionalUnplaced",v.unplaced},{"settings",QJsonObject{{"vertexOffset",QString::number(d.vertices+qint64(d.first)*d.stride)},{"vertexCount",d.count},{"indexCount",d.indexCount}}},{"basis",QString("Native ARCX mesh/material/buffer references; primitive %1, layout %2, stride %3; hierarchy transform %4. Source material: %5. Primary color texture uses native material/image indices; advanced shader passes are not emulated.").arg(d.primitive).arg(d.layout).arg(d.stride).arg(v.node>=0?"applied":"unavailable (local geometry)",d.materialName)}};}
